____
}

problem_set.solution:
function memoize(fn: (n: number) => number) {
  const cache = new Map<number, number>();
  let hits = 0;
  let misses = 0;
  return {
    call(n: number): number {
      const cached = cache.get(n);
      if (cached !== undefined) {
        hits++;
        return cached;
      }
      misses++;
      const value = fn(n);
      cache.set(n, value);
      return value;
    },
    stats: () => `hits=${hits} misses=${misses}`,
  };
}

