  const op = Object.hasOwn(ops, name) ? ops[name] : undefined;
  if (op === undefined) {
    unknown = name;
    break;
  }
  value = op(value);
  seen.push(value);
}
if (seen.length > 0) console.log(seen.join(" "));
if (unknown !== "") console.log(`unknown ${unknown}`);

