  else if (c === "F" || c === "B") {
    const s = c === "F" ? 1 : -1;
    x += dx * s;
    y += dy * s;
    far = Math.max(far, Math.abs(x) + Math.abs(y));
  }
}
console.log(`${x},${y}`);
console.log(ORDER[h]);
console.log(far);

