import * as fs from "fs";
const input = fs.readFileSync(0, "utf8").trim();
type Block =
  | { kind: "heading"; level: number; text: string }
  | { kind: "list"; items: string[] }
  | { kind: "rule" }
  | { kind: "paragraph"; lines: string[] };
