    if (Array.isArray(value)) for (const v of value) walk(v);
    else out.push(value);
  };
  walk(xs);
  return out as FlattenDeep<T>[];
}
function depth(value: unknown): number {
  return Array.isArray(value) ? 1 + Math.max(0, ...value.map(depth)) : 0;
}
