  const [cmd = "", a = "", b = "", c = ""] = line.trim().split(/\s+/);
  if (cmd === "open") {
    const acc = Account.open(a, b, c === "" ? NaN : Number(c));
    if (typeof acc === "string") console.log(`refused: ${acc}`);
    else {
      accounts.set(acc.id, acc);
      console.log(`opened ${acc.id}`);
    }
