    const problems = check(i + 1, r);
    const first = problems[0];
    if (mode === "fail-fast" && first !== undefined) throw first;
    all.push(...problems);
  });
  if (all.length > 0) throw new AggregateError(all, `${all.length} problems`);
  return records.length;
}
