    for (;;) {
      await new Promise<void>((r) => setTimeout(r, 0));
      this.#timers.sort((a, b) => a.at - b.at || a.seq - b.seq);
      const next = this.#timers.shift();
      if (next === undefined) return;
      this.now = next.at;
      next.fire();
    }
  }
