    const outcome = await attemptOnce(r.attempts[k - 1] ?? { ok: false, ms: 1 });
    console.log(`t=${clock.now} ${r.name} attempt ${k} ${outcome}`);
    if (outcome === "ok") return { result: { ok: true, value: clock.now }, tries: k };
