  for (const cur of sorted) {
    const last = out.at(-1);
    if (last !== undefined && cur[0] <= last[1] + 1) out[out.length - 1] = [last[0], Math.max(last[1], cur[1])];
    else out.push(cur);
  }
  return out;
}
