function parseCents(s: string): Result<Cents> {
  const m = /^(-?)(\d+)(?:\.(\d{1,2}))?$/.exec(s);
  if (m === null) return err("bad amount");
  const cents = Number(m[2] ?? "0") * 100 + Number((m[3] ?? "").padEnd(2, "0"));
  return ok((m[1] === "-" ? -cents : cents) as Cents);
