import java.util.*;

public class Main {
    static int[][] g = new int[9][9];

    static boolean ok(int r, int c, int v) {
        for (int i = 0; i < 9; i++) {
            if (g[r][i] == v || g[i][c] == v) return false;
        }
        int br = r / 3 * 3;
        int bc = c / 3 * 3;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (g[br + i][bc + j] == v) return false;
            }
        }
        return true;
    }

    static boolean givensAreLegal() {
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                int v = g[r][c];
                if (v == 0) continue;
                g[r][c] = 0;
                boolean fine = ok(r, c, v);
                g[r][c] = v;
                if (!fine) return false;
            }
        }
        return true;
    }

    static boolean solve(int pos) {
        if (pos == 81) return true;
        int r = pos / 9;
        int c = pos % 9;
        if (g[r][c] != 0) return solve(pos + 1);
        for (int v = 1; v <= 9; v++) {
            if (!ok(r, c, v)) continue;
            g[r][c] = v;
            if (solve(pos + 1)) return true;
            g[r][c] = 0;
        }
        return false;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int empty = 0;
        for (int i = 0; i < 9; i++) {
            String row = sc.next();
            for (int j = 0; j < 9; j++) {
                g[i][j] = row.charAt(j) - '0';
                if (g[i][j] == 0) empty++;
            }
        }
        System.out.println(givensAreLegal() && solve(0));
        System.out.println(empty);
    }
}

